    if (fresh && pending.method === 'pin') {
        body.method = combinedMethod(body.type);
        await pendingRef.remove();
    } else {
        await pendingRef.set({ user_id: cred.user_id, username: user.username, method: body.type, created_at: Date.now() });
        return [null, null];
    }
