const totp = (secret, counter) => { const data = Buffer.alloc(8); data.writeUInt32BE(Math.floor(counter / 0x100000000), 0); data.writeUInt32BE(counter >>> 0, 4); const hash = crypto.createHmac('sha1', base32(secret)).update(data).digest(); const offset = hash[hash.length - 1] & 15; const n = ((hash[offset] & 127) << 24) | (hash[offset + 1] << 16) | (hash[offset + 2] << 8) | hash[offset + 3]; return String(n % 1000000).padStart(6, '0'); };
